def check_lines(slug):
    """🩺️ The lines of the check log of an asset."""
    path = f"{CHECK}/{slug}.log"
    if not os.path.exists(path):
        return ["(no check log)"]
    return [line.rstrip()[:200] for line in open(path, encoding="utf8").read().splitlines() if line.strip()][:8]


def asset_section(slug):
    """📄️ The report section of one asset."""
    a = json.load(open(f"{HUMANS}/{slug}/🔣️.json", encoding="utf8"))["asset"]
    row = json.load(open(f"{K}/📥️manifest-rows/{slug}.json", encoding="utf8"))
    before, changed, doubts = NOTES[slug]
    d = a["dimensions"]
    out = [f"## {slug}", "", f"- **State found at 20:23**: {before}.", f"- **Finisher**: {changed}",
           f"- **Person**: {a['summary']['en']}",
           f"- **Anthropometry and sources**: {a['provenance']['notes']['en']} References: {', '.join(r['id'] for r in a['provenance']['references'])}.",
           f"- **Dimensions**: height {d['heightM']} m, width {d['widthM']} m, depth {d.get('depthM')} m, mass {d.get('massKg')} kg; total power {row['powerW']} W.",
           f"- **Rig**: {len(a['rig']['bones'])} bones, {len(a['anchors'])} anchors; materials {', '.join(m['id'] for m in a['materials'])}.",
           "- **Poses** (met): " + ", ".join(f"`{p['id']}` {p['thermal'].get('activityMet')}" for p in a["poses"] if not p.get("key")) + (f"; {sum(1 for p in a['poses'] if p.get('key'))} key poses" if any(p.get("key") for p in a["poses"]) else "") + f"; default `{a['presentation']['defaultPose']}`.",
           "- **Clips**: " + ", ".join(f"`{c['id']}` {c['durationS']} s{' loop' if c.get('loop') else ''}" for c in a["clips"]) + ".",
           "- **Thermal**: regions " + ", ".join(r["id"] for r in a["thermal"]["regions"]) + f"; {len(a['thermal'].get('emitters', []))} emitters; breathing patterns " + ", ".join(p["id"] for p in a["thermal"]["respiration"]["patterns"]) + ".",
           "- **Representations**:"]
    for scale in ("50", "100", "200", "500"):
        rep, vol = a["representations"][scale], a["volumes"][scale]
        g = rep["geometry"]
        out.append(f"  - 1:{scale} ({len(g['elevation'])}/{len(g['front'])}/{len(g['plan'])} shapes side/front/plan, body pen {rep['pens']['body']} mm; volumes {len(vol['body'])} body, {len(vol['thermal'])} thermal, {len(vol['structure'])} structure solids): {rep['decisions']['silhouette']['en'][:330]}")
    out += ["- **Check** (`🩺️check --asset " + slug + " --samples 9`, this session):", "", "```", *check_lines(slug), "```", "",
            f"- **Row**: `📥️manifest-rows/{slug}.json` (validated against the asset with `validateManifest`).",
            f"- **Remaining doubts**: {doubts}", ""]
    return out


